        CouchbaseEnvironment environment = DefaultCouchbaseEnvironment
                .builder()
                .bootstrapCarrierDirectPort(couchbase.getBootstrapCarrierDirectPort())
                .bootstrapHttpDirectPort(couchbase.getBootstrapHttpDirectPort())
                .build();

